import type { NextApiRequest, NextApiResponse } from 'next';
import { spawn } from 'child_process';
import path from 'path';

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end('Method Not Allowed');

  const { text } = req.body;
  const scriptPath = path.join(process.cwd(), 'scripts', 'my_script.py');

  const py = spawn('python3', [scriptPath, text]);

  let output = '';
  let errorOutput = '';

  py.stdout.on('data', (data) => {
    output += data.toString();
  });

  py.stderr.on('data', (data) => {
    errorOutput += data.toString();
  });

  py.on('close', (code) => {
    if (code === 0) {
      res.status(200).json({ result: output.trim() });
    } else {
      res.status(500).json({ error: errorOutput || 'Lỗi không xác định từ Python script.' });
    }
  });
}
